module skid_buffer_core (
    input wire clk,
    input wire rst,
    input wire [7:0] in_data,
    input wire in_valid,
    output wire in_ready,
    output wire [7:0] out_data,
    output wire out_valid,
    input wire out_ready
);

    reg [7:0] data0;
    reg [7:0] data1;
    reg [1:0] count;

    wire push;
    wire pop;

    assign in_ready = (count < 2) || out_ready;
    assign out_valid = (count != 0);
    assign out_data = data0;

    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0;
        end else begin
            case (count)
                2'd0: begin
                    if (push) begin
                        data0 <= in_data;
                        count <= 2'd1;
                    end
                end

                2'd1: begin
                    if (push && pop) begin
                        data0 <= in_data;
                    end else if (push) begin
                        data1 <= in_data;
                        count <= 2'd2;
                    end else if (pop) begin
                        count <= 2'd0;
                    end
                end

                2'd2: begin
                    if (pop) begin
                        data0 <= data1;
                        if (push) begin
                            data1 <= in_data;
                            count <= 2'd2;
                        end else begin
                            count <= 2'd1;
                        end
                    end
                end

                default: begin
                    count <= 2'd0;
                end
            endcase
        end
    end

endmodule
